(()=>{'use strict';const e='محمدحسین عسگری ثمرین';document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-legacy-identity]').forEach(t=>t.textContent=e);const t=document.getElementById('scrollTop');t&&t.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}),{once:true})});})();
